// Des: Tests failover: failures skip a day, denied skips month
// Flo: temp db > record outcomes > assert who is okay at which time
// I/O: temp db + fixed clock > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const fail = @import("ru-fail-over.zig"); const inde = @import("st-page-inde.zig"); const sqli = @import("st-stor-sqli.zig"); const civi = @import("ut-date-civi.zig");
const allo = std.testing.allocator;
const DAYZ: i64 = 86400000;
const NOWZ: i64 = 1795528470301;
const Rigg = struct { tmpz: std.testing.TmpDir, dirz: []u8, dbzz: sqli.Dbzz,
pub fn upzz(self: *Rigg) !void { self.tmpz = std.testing.tmpDir(.{}); self.dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{self.tmpz.sub_path}); self.dbzz = try inde.pageOpen(allo, std.testing.io, self.dirz); }
pub fn down(self: *Rigg) void { self.dbzz.close(); allo.free(self.dirz); self.tmpz.cleanup(); } };
test "an unknown vendor is okay; N failures in a row skip it for a day, then it is okay again" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try std.testing.expect(try fail.failOkay(&rig3.dbzz, "turs", NOWZ)); try fail.failBadz(&rig3.dbzz, "turs", NOWZ, false, 3); try fail.failBadz(&rig3.dbzz, "turs", NOWZ, false, 3); try std.testing.expect(try fail.failOkay(&rig3.dbzz, "turs", NOWZ)); try fail.failBadz(&rig3.dbzz, "turs", NOWZ, false, 3); try std.testing.expect(!try fail.failOkay(&rig3.dbzz, "turs", NOWZ + 1000)); try std.testing.expect(!try fail.failOkay(&rig3.dbzz, "turs", NOWZ + DAYZ - 1)); try std.testing.expect(try fail.failOkay(&rig3.dbzz, "turs", NOWZ + DAYZ + 1)); }
test "a success resets the count: two failures, one success, two more failures stay okay" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try fail.failBadz(&rig3.dbzz, "b2zz", NOWZ, false, 3); try fail.failBadz(&rig3.dbzz, "b2zz", NOWZ, false, 3); try fail.failGood(&rig3.dbzz, "b2zz"); try fail.failBadz(&rig3.dbzz, "b2zz", NOWZ, false, 3); try fail.failBadz(&rig3.dbzz, "b2zz", NOWZ, false, 3); try std.testing.expect(try fail.failOkay(&rig3.dbzz, "b2zz", NOWZ)); }
test "denied (blocked or suspended) skips the vendor until the first of next month" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try fail.failBadz(&rig3.dbzz, "turs", NOWZ, true, 3); const nxtz = civi.civiNext(NOWZ); try std.testing.expectEqual(nxtz, try fail.failUnti(&rig3.dbzz, "turs")); try std.testing.expect(!try fail.failOkay(&rig3.dbzz, "turs", nxtz - 1)); try std.testing.expect(try fail.failOkay(&rig3.dbzz, "turs", nxtz)); try fail.failGood(&rig3.dbzz, "turs"); try std.testing.expect(try fail.failOkay(&rig3.dbzz, "turs", NOWZ)); }
test "full and nothing to purge skips a day but never shortens a month-long block" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try fail.failFull(&rig3.dbzz, "b2zz", NOWZ); try std.testing.expectEqual(NOWZ + DAYZ, try fail.failUnti(&rig3.dbzz, "b2zz")); try fail.failBadz(&rig3.dbzz, "r2zz", NOWZ, true, 3); const mont = try fail.failUnti(&rig3.dbzz, "r2zz"); try fail.failFull(&rig3.dbzz, "r2zz", NOWZ); try std.testing.expectEqual(mont, try fail.failUnti(&rig3.dbzz, "r2zz")); }
test "first healthy pick follows config order, honors skip list, null when all are blocked" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const orde = [_][]const u8{ "b2zz", "r2zz", "tigr" }; try std.testing.expectEqual(@as(?usize, 0), try fail.failFirs(&rig3.dbzz, &orde, &.{}, NOWZ)); try fail.failBadz(&rig3.dbzz, "b2zz", NOWZ, true, 3); try std.testing.expectEqual(@as(?usize, 1), try fail.failFirs(&rig3.dbzz, &orde, &.{}, NOWZ)); try std.testing.expectEqual(@as(?usize, 2), try fail.failFirs(&rig3.dbzz, &orde, &.{"r2zz"}, NOWZ)); try fail.failBadz(&rig3.dbzz, "r2zz", NOWZ, true, 3); try fail.failBadz(&rig3.dbzz, "tigr", NOWZ, true, 3); try std.testing.expectEqual(@as(?usize, null), try fail.failFirs(&rig3.dbzz, &orde, &.{}, NOWZ)); try std.testing.expectEqual(@as(?usize, 0), try fail.failFirs(&rig3.dbzz, &orde, &.{}, civi.civiNext(NOWZ))); }
test "flags default to zero and keep the last value" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try std.testing.expectEqual(@as(i64, 0), try fail.flagGetz(&rig3.dbzz, "veri_last")); try fail.flagSetz(&rig3.dbzz, "veri_last", 42); try fail.flagSetz(&rig3.dbzz, "veri_last", 99); try std.testing.expectEqual(@as(i64, 99), try fail.flagGetz(&rig3.dbzz, "veri_last")); }
test "a ping resets the failure count but never clears a block or a full mark" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try fail.failBadz(&rig3.dbzz, "b2zz", NOWZ, false, 3); try fail.failBadz(&rig3.dbzz, "b2zz", NOWZ, false, 3); try fail.failPing(&rig3.dbzz, "b2zz", NOWZ); try fail.failBadz(&rig3.dbzz, "b2zz", NOWZ, false, 3); try fail.failBadz(&rig3.dbzz, "b2zz", NOWZ, false, 3); try std.testing.expect(try fail.failOkay(&rig3.dbzz, "b2zz", NOWZ)); try fail.failFull(&rig3.dbzz, "r2zz", NOWZ); try fail.failPing(&rig3.dbzz, "r2zz", NOWZ + 1000); try std.testing.expect(!try fail.failOkay(&rig3.dbzz, "r2zz", NOWZ + 2000)); try fail.failBadz(&rig3.dbzz, "tigr", NOWZ, true, 3); try fail.failPing(&rig3.dbzz, "tigr", NOWZ + 1000); try std.testing.expectEqual(civi.civiNext(NOWZ), try fail.failUnti(&rig3.dbzz, "tigr")); }
